beforeFunction=function(sta){
    var a=$("#收货数量").val();
    var b=$("#待收数量").val();
    if (a*1>b*1)
    {
        alert("lang:{zh:收货数量超出待收数量，不允许,en:Received quantity exceeds pending quantity,de:Empfangene Menge übersteigt ausstehende Menge}");
        return true;
    }
    else
    {
        return false;
    }
}


